ALTER TABLE "payment_term_catalog"."payment_term_revisions" DROP CONSTRAINT "payment_term_catalog_revisions_semantics_ck", ADD CONSTRAINT "payment_term_catalog_revisions_semantics_ck" CHECK (("semantic_kind" = 'IMMEDIATE' and "net_days" is null and "due_date_anchor" is null and "calendar_rule" = 'NOT_APPLICABLE') or ("semantic_kind" = 'NET_DAYS' and "net_days" between 0 and 9007199254740991 and "due_date_anchor" = 'INVOICE_ISSUED_AT' and "calendar_rule" = 'CALENDAR_DAYS_UTC'));